{
  "items": [
    {
      "name": "MvPolynomial.homogeneousComponent_apply",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommSemiring R] (n : ℕ) (φ : MvPolynomial σ R),\n  (MvPolynomial.homogeneousComponent n) φ =\n    ∑ d ∈ φ.support with Finsupp.degree d = n, (MvPolynomial.monomial d) (MvPolynomial.coeff d φ)"
    },
    {
      "name": "MvPolynomial.sum_homogeneousComponent",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommSemiring R] (φ : MvPolynomial σ R),\n  ∑ i ∈ Finset.range (φ.totalDegree + 1), (MvPolynomial.homogeneousComponent i) φ = φ"
    },
    {
      "name": "MvPolynomial.eval_eq",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (X : σ → R) (f : MvPolynomial σ R),\n  (MvPolynomial.eval X) f = ∑ d ∈ f.support, MvPolynomial.coeff d f * ∏ i ∈ d.support, X i ^ d i"
    },
    {
      "name": "MvPowerSeries.subst_monomial",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R] {τ : Type u_4} {S : Type u_5} [inst_1 : CommRing S]\n  [inst_2 : Algebra R S] {a : σ → MvPowerSeries τ S},\n  MvPowerSeries.HasSubst a →\n    ∀ (e : σ →₀ ℕ) (r : R),\n      MvPowerSeries.subst a ((MvPowerSeries.monomial e) r) =\n        (algebraMap R (MvPowerSeries τ S)) r * e.prod fun s n => a s ^ n"
    },
    {
      "name": "MvPowerSeries.constantCoeff_subst",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Substitution",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommRing R] {τ : Type u_4} {S : Type u_5} [inst_1 : CommRing S]\n  [inst_2 : Algebra R S] {a : σ → MvPowerSeries τ S},\n  MvPowerSeries.HasSubst a →\n    ∀ (f : MvPowerSeries σ R),\n      MvPowerSeries.constantCoeff (MvPowerSeries.subst a f) =\n        ∑ᶠ (d : σ →₀ ℕ), (MvPowerSeries.coeff d) f • MvPowerSeries.constantCoeff (d.prod fun s e => a s ^ e)"
    }
  ]
}
